// Spawns a short-lived particle at a position with a given velocity.
unsigned char *spawn_projectile_expiry_particle(char *pos, char *vec) {
    unsigned char *p = create_part(0x33);
    if (p != 0) {
        char *b = (unsigned char *)((struct PartBase *)p)->data;
        char *a = (unsigned char *)&((struct PartBase *)p)->pos;
        qcopy(a, pos);
        qcopy(b, vec);
        ((struct PartBase *)p)->color = 0x5E806040;
        ((struct PartBase *)p)->unk_09 = truncate_float_to_s32_r(4.0f) + 0x40;
        ((struct PartBase *)p)->blend = 0x48;
        ((struct PartBase *)p)->unk_01 = 0;
        ((struct PartBase *)p)->spin = 0;
        ((struct PartBase *)p)->texture = *umbris_part_type51_textures;
        ((struct PartBase *)p)->timer = 0x78;
        ((struct PartBase *)p)->size = 6300.0f;
    }
    return p;
}
