        /* FAKEMATCH: volatile: store order unk_09, blend, unk_01, size (6/376 bytes differ without it). */
        *(volatile unsigned char *)&((struct PartBase *)p)->unk_01 = 0;
        /* FAKEMATCH: volatile: store order unk_09, blend, unk_01, size (6/376 bytes differ without it). */
